              text: 'When a skilled reader reads: "The old fig tree spread its arms over the dry creek bed. Magpies carolled in the early morning while the first light made the dew sparkle like scattered glass."\n\nThey automatically SEE:\n• A large, spreading tree\n• A dry creek — red Australian earth\n• Magpies singing at dawn\n• Dewdrops catching sunlight\n\nThis mental image HELPS comprehension. If you can see it, you understand it better and remember it longer.',
