              text: 'Your mind movie should include ALL senses:\n\nSIGHT: What does the scene look like?\nSOUND: What can you hear? (The magpies calling, the silence of the empty creek)\nSMELL: What does the air smell like? (Early morning, eucalyptus, damp earth)\nTOUCH: What would the textures feel like? (Rough bark, cool dew)\nMOOD: What atmosphere does the scene have? (Peaceful, lonely, hopeful)\n\nGood texts give you sensory clues. Your job is to use them!',
