        teacherNote: 'Read the annotated text aloud together. Highlight each structural part in a different colour — students often find it easier to understand structure through colour-coding.',
        imagePrompt: 'A Year 4 classroom anchor chart showing the four parts of a persuasive text: position, arguments, evidence, call to action, with arrows and Australian school examples.',
        content: {
          heading: 'Persuasive Text: "Our School Should Have a Vegetable Garden"',
          body: [
            {
              label: '📌 Position Statement',
              text: '"Our school should build a vegetable garden on the unused land beside the oval."\n\nThe position statement comes FIRST. It tells the reader exactly what you believe. It should be clear and confident — not wishy-washy. WEAK: "Maybe it would be nice if we had a garden." STRONG: "Our school must build a vegetable garden immediately."',
              highlight: 'blue',
            },
            {
              label: '💪 Arguments + Evidence',
              text: '"Firstly, a garden teaches students where food comes from. Research shows that children who grow food are more likely to eat vegetables. Furthermore, tending plants reduces stress and improves focus — and our school canteen could use the fresh produce, saving money.\n\nFINALLY — wait, that\'s a connective! Connectives guide the reader:\n• Firstly / To begin with — introduces first argument\n• Furthermore / In addition — adds more points\n• However — introduces a counter-argument\n• In conclusion / Ultimately — wraps up',
              highlight: 'green',
            },
            {
              label: '📣 Emotive Language & Call to Action',
              text: 'EMOTIVE WORDS make the reader FEEL something:\n• "Our children deserve fresh, healthy food."\n• "Every day we delay, another opportunity is wasted."\n• "Imagine how proud students would feel harvesting their own food!"\n\nCALL TO ACTION — ends the text by telling the reader what to do:\n"We urge the principal and school council to approve this proposal at next month\'s meeting. Sign our petition today — because our children\'s health cannot wait."',
              highlight: 'orange',
            },
          ],
          questions: [
            { q: 'What are the four main parts of a persuasive text?', a: 'Position statement, arguments, evidence, and a call to action.' },
            { q: 'Give two connectives that add more arguments.', a: 'Furthermore / In addition / Moreover / Also (any two).' },
            { q: 'What is the purpose of emotive language in persuasive writing?', a: 'To make the reader feel something (e.g. concern, pride, urgency) so they are more likely to agree with the writer.' },
          ],
        },
