              text: '"How to Plant Native Australian Seeds"\nYou will need: approximately 30 minutes\n\nPlanting native seeds helps support local ecosystems. This guide will show you how to successfully germinate and plant native Australian seeds in your school garden.\n\nTIPS for a strong goal section:\n• State the PURPOSE (why would someone do this?)\n• Give a realistic TIME estimate\n• Name the AUDIENCE if relevant ("This guide is suitable for Year 3–6 students.")\n• Keep it SHORT — the goal is not the procedure, just the setup',
