        prompt: 'Write a complete procedural text (how-to guide or recipe) about something you know how to do. Include: a clear goal/title, a materials or equipment list with exact quantities, and numbered steps using imperative verbs. Choose: (a) a simple recipe, (b) a craft or art project, or (c) a game or sport set-up.',
