    title: 'Explanation Texts',
    victorianCode: 'VCELY319',
    description: 'Learn how explanation texts work, how to structure them, and how to use technical vocabulary and logical connectives to explain how things happen.',
    yearLevel: 4,
    estimatedMinutes: 60,
