              text: 'Speak loud enough for the back of the room. Project from your diaphragm — not a shout, but supported voice. Pace: speak SLOWER than feels natural when nervous (nerves make us rush). Vary your pace — slow down for important points, speed up slightly to build excitement.',
              highlight: 'The most common feedback on student presentations: "too quiet" and "too fast". Practise projecting to the back row and deliberately slowing your pace on key sentences.',
