        teacherNote: "This worked example reviews the full writing process. Use a real student piece from earlier in the year (with permission) or a model text you wrote, and show the journey from rough plan to polished draft. Emphasise that ALL professional writers revise.",
        imagePrompt: 'A circular writing process diagram: Plan → Draft → Revise → Edit → Publish → Reflect — with examples at each stage, vibrant Year 4 classroom poster style',
        content: {
          heading: 'The Five-Stage Writing Process',
          body: [
            {
              label: 'Plan and Draft',
              text: 'Planning: brainstorm, map or list your ideas BEFORE writing. For narrative: map your story mountain (orientation, complication, resolution). For persuasion: list your arguments and evidence. For poetry: brainstorm images, feelings, sounds. Drafting: write without stopping to fix every word — get the ideas down. The first draft is SUPPOSED to be imperfect.',
              highlight: "The planning stage is where great writing is born. Writers who skip the plan often wander, lose direction, or run out of ideas halfway. Even 5 minutes of planning makes a huge difference.",
            },
            {
              label: 'Revise and Edit',
              text: 'Revise = making the WRITING better (Is my idea clear? Is this the best word? Can I add a detail here?). Edit = fixing ERRORS (spelling, punctuation, grammar, sentences). These are TWO separate passes. Revising first, editing second. Common revision moves: adding vivid details, varying sentence length, strengthening the opening/closing, cutting unnecessary words.',
              highlight: "Most students edit too early (fix spelling before the ideas are right) and do not revise at all (change nothing once the draft is done). Revising is where the MAGIC happens — it is not fixing mistakes, it is upgrading your vision.",
            },
            {
              label: 'Publish and Reflect',
              text: 'Publishing gives your writing a real audience — it could be read aloud, displayed, typed up, illustrated, or shared with family. Reflecting: ask yourself — What am I most proud of? What would I do differently next time? What is one writing goal for Year 5?',
              highlight: "Publishing matters because writing for an audience changes how you write. Knowing someone will actually read your work makes you care more — about clarity, about impact, about every single word choice.",
            },
          ],
          questions: [
            { q: 'What is the difference between REVISING and EDITING?', a: 'Revising improves the writing itself — ideas, structure, language choices, voice. Editing fixes surface errors — spelling, punctuation and grammar. Revise first, edit second.' },
            { q: 'Why is drafting without stopping to fix every word important?', a: 'Getting ideas down without interruption keeps your creative flow going. If you stop to fix every word, you lose the thread of your ideas. Fix things in the revision/edit stage.' },
            { q: 'Why does publishing your writing to a real audience matter?', a: 'A real audience makes the purpose concrete — you write more carefully, more clearly and with more pride when you know someone will genuinely read it.' },
          ],
        },
